  "html": "<h3>각도가 왜 따로 문제가 되나</h3><p>임플란트 식립 각도는 잇몸뼈에 박히는 픽스처가 어느 방향으로 기울어져 있는지를 말합니다. 자연 치아 뿌리가 씹는 힘을 길이 방향으로 받듯, 임플란트도 힘이 축 방향으로 전달될 때 나사와 주변 뼈에 무리가 덜 갑니다. 각도가 틀어지면 위에 올릴 크라운이 한쪽으로 돌출되거나, 나사 구멍이 치아 앞면으로 나오는 등 보철 설계가 까다로워집니다.</p><h3>각도를 정할 때 함께 보는 것</h3><ul><li>뼈의 모양: 앞니 부위는 뼈가 바깥쪽으로 기울어 있어 그대로 따라가면 각도가 벌어짐</li><li>피해야 할 구조: 아래턱 신경관, 위턱 상악동, 이웃 치아 뿌리</li><li>최종 치아 위치: 크라운이 서야 할 자리에서 거꾸로 거슬러 올라가 축을 정함</li></ul><h3>각도를 맞추는 방법</h3><p>CBCT와 구강 스캔을 겹쳐 컴퓨터에서 위치와 방향을 먼저 설계하고, 필요하면 그 설계대로 드릴 방향을 잡아 주는 수술용 가이드를 씁니다. 뼈 사정상 어느 정도 기울여 심어야 할 때는 각도가 꺾인 지대주를 써서 보철 방향을 보정하기도 합니다. 어느 정도까지 허용되는지는 제품과 부위에 따라 다릅니다.</p><h3>여러 개를 심을 때는 서로의 방향도 중요</h3><p>임플란트 두세 개를 연결해 브릿지처럼 쓰거나, 틀니를 고정하는 경우에는 각 픽스처가 서로 비슷한 방향을 향해야 보철물이 한 번에 끼워집니다. 방향이 제각각이면 연결 부품으로 보정해야 하고 청소도 어려워집니다. 반대로 무치악 턱에서 뒤쪽 임플란트를 일부러 비스듬히 심어 상악동이나 신경을 피하는 설계도 있어, 각도는 단독이 아니라 전체 계획 안에서 정해집니다.</p>",
